/* saveDisconnectUser - Lee JiSeob */
UPDATE SAA200 C /* 사용자 */
SET C.USER_CNTN_INTRCP_YN = #{DISCONNECT_YN}, C.USER_CNTN_INTRCP_SE_CD = #{DISCONNECT_CODE}, C.USER_CNTN_INTRCP_CS_CN = #{DISCONNECT_REASON}, C.LAST_MDFR_ID = #{USER_ID2}, C.LAST_MDFCN_DT = SYSDATE
WHERE C.USER_ID = #{USER_ID}
